#include<bits/stdc++.h>

using namespace std;

const int K = 3;
const int INF = int(1e9);

pair<int, int> get_segment(char c)
{
if(c == '0') return {K, K};
if(c == '-') return {0, K - 1};
return {K + 1, K * 2};
}

void solve()
{
int n;
string s;
cin >> n >> s;
vector<vector<int>> dp(n + 1, vector<int>(2 * K + 1, INF));
dp[0][K] = 0;
for(int i = 0; i < n; i++)
for(int j = 0; j < 2 * K + 1; j++)
{
if(dp[i][j] == INF) continue;
auto [l, r] = get_segment(s[i]);
for(int k = l; k <= r; k++)
{
if(k == j) continue;
int& d = dp[i + 1][k];
d = min(d, max(dp[i][j], abs(k - j)));
}
}
int ans = *min_element(dp[n].begin(), dp[n].end());
if(ans == INF) ans = -1;
cout << ans << endl;
}

int main()
{
ios_base::sync_with_stdio(0);
cin.tie(0);
int t;
cin >> t;
for(int i = 0; i < t; i++)
solve();
}

